// Busca la reunión futura del cliente en el CALENDARIO DE REUNIONES, cruzando por teléfono.
// Entrada: eventos del nodo "Reuniones - Get Many" (solo futuras).
// IMPORTANTE: ajustá la ruta del teléfono si tu nodo no se llama 'Edit Fields2'.
const telefono = $('Edit Fields2').first().json.usuario;
const objetivo = String(telefono || '').replace(/\D/g, '').slice(-10); // últimos 10 dígitos

const eventos = $input.all().map(i => i.json);

function fmt(iso) {
  if (!iso) return null;
  try {
    return new Date(iso).toLocaleString('es-AR', {
      timeZone: 'America/Argentina/Buenos_Aires', dateStyle: 'full', timeStyle: 'short'
    });
  } catch (e) { return iso; }
}

let reunion = { tiene: false, fecha_hora_texto: null, titulo: null };
if (objetivo) {
  for (const ev of eventos) {
    const digitos = `${ev.summary || ''} ${ev.description || ''} ${ev.location || ''}`.replace(/\D/g, '');
    if (digitos.includes(objetivo)) {
      const inicio = ev.start?.dateTime || ev.start?.date || null;
      reunion = { tiene: true, fecha_hora_texto: fmt(inicio), titulo: ev.summary || null };
      break;
    }
  }
}
return [{ json: { reunion_cliente: reunion } }];
